void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float BLUR_SIZE = iMouse.y/iResolution.y;

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Output pixel color goes here
    vec4 col = vec4(0);

    // Iterate over blur samples
    for(float index=0.; index < 10.; index++)
    {
        // Calculate sample offset (range 0-1)
        float sampleOffset = index/9.;

        // Get uv coordinate of sample
        vec2 sampleUV = uv + vec2(0, (sampleOffset - 0.5) * BLUR_SIZE);
        //add color at position to color
        col += texture(iChannel0, sampleUV);
    }

    // Divide the sum of values by the amount of samples
    col = col / 10.;

    // Output to screen
    fragColor = col;
}
